function fixedPanelText(scene,text,parent,size=.28,color='#ffffff',y=0,z=-.24){
  const lines=String(text).split('\n').slice(0,3), maxLen=Math.max(5,...lines.map(s=>s.length));
  const scale=Math.max(.75,size/.28), width=Math.max(.75,Math.min(2.6,maxLen*.095))*scale, height=(.34+.19*(lines.length-1))*scale;
  const p=B.MeshBuilder.CreatePlane('panelText',{width,height},scene);p.parent=parent;p.position=new B.Vector3(0,y,z);p.isPickable=false;
  const tex=new B.DynamicTexture('panelTextTex',{width:768,height:256},scene,true);tex.hasAlpha=true;
  const c=tex.getContext();c.clearRect(0,0,768,256);c.textAlign='center';c.textBaseline='middle';c.font=`900 ${Math.round(68*Math.min(1,scale))}px Arial`;c.fillStyle=color;
  lines.forEach((s,i)=>c.fillText(s,384,128+(i-(lines.length-1)/2)*66));tex.update();
  const m=new B.StandardMaterial('panelTextMat',scene);m.diffuseTexture=tex;m.emissiveTexture=tex;m.opacityTexture=tex;m.disableLighting=true;m.backFaceCulling=false;p.material=m;
  G.lobbyMeshes.push(p);return p;
}

function mtlRgbToHex(parts){
  const nums=parts.map(v=>Math.max(0,Math.min(255,Math.round(parseFloat(v)*255))));
  return '#'+nums.map(v=>v.toString(16).padStart(2,'0')).join('');
}
function parseSimpleMtl(txt=''){
  const mats={}; let cur=null;
  for(const raw of String(txt).split('\n')){
    const line=raw.trim(); if(!line||line.startsWith('#')) continue;
    const parts=line.split(/\s+/); const cmd=parts.shift();
    if(cmd==='newmtl'){ cur={name:parts.join(' '),color:'#b8b0a2',alpha:1,emissive:false}; mats[cur.name]=cur; }
    else if(cmd==='Kd'&&cur) cur.color=mtlRgbToHex(parts);
    else if(cmd==='d'&&cur) cur.alpha=Math.max(.1,Math.min(1,parseFloat(parts[0]||'1')));
    else if(cmd==='Ke'&&cur) cur.emissive=parts.some(v=>parseFloat(v)>0.01);
  }
  return mats;
}
function buildEmbeddedObj(scene,name,objText,mtlText,opt={}){
  if(!objText) return null;
  const mats=parseSimpleMtl(mtlText||'');
  const verts=[null]; const groups={}; let current='Default';
  function grp(n){ if(!groups[n]) groups[n]={positions:[],indices:[]}; return groups[n]; }
  for(const raw of String(objText).split('\n')){
    const line=raw.trim(); if(!line||line.startsWith('#')) continue;
    if(line.startsWith('v ')){
      const p=line.split(/\s+/); verts.push([parseFloat(p[1]),parseFloat(p[2]),parseFloat(p[3])]);
    }else if(line.startsWith('usemtl ')) current=line.slice(7).trim()||'Default';
    else if(line.startsWith('f ')){
      const refs=line.slice(2).trim().split(/\s+/).map(tok=>{
        let idx=parseInt(tok.split('/')[0],10); if(Number.isNaN(idx)) return null; if(idx<0) idx=verts.length+idx; return idx;
      }).filter(Boolean);
      if(refs.length<3) continue;
      const g=grp(current);
      for(let i=1;i<refs.length-1;i++){
        const tri=[refs[0],refs[i],refs[i+1]];
        for(const id of tri){ const v=verts[id]; if(!v) continue; g.positions.push(v[0],v[1],v[2]); g.indices.push(g.indices.length); }
      }
    }
  }
  const root=new B.TransformNode(name,scene); root.rotationQuaternion=null;
  for(const [matName,data] of Object.entries(groups)){
    if(!data.positions.length) continue;
    const mesh=new B.Mesh(name+'_'+matName.replace(/[^a-z0-9_\-]/gi,'_'),scene);
    const vd=new B.VertexData(); vd.positions=data.positions; vd.indices=data.indices; const normals=[]; B.VertexData.ComputeNormals(vd.positions,vd.indices,normals); vd.normals=normals; vd.applyToMesh(mesh,false);
    const md=mats[matName]||{color:'#c8b8a2',alpha:1};
    const material=new B.PBRMaterial(mesh.name+'_mat',scene); material.albedoColor=B.Color3.FromHexString(md.color||'#c8b8a2'); material.roughness=.88; material.metallic=.03; material.alpha=md.alpha??1;
    const low=(matName||'').toLowerCase();
    if(low.includes('glass')){ material.alpha=.35; material.metallic=.1; material.roughness=.08; }
    if(low.includes('light')){ material.emissiveColor=B.Color3.FromHexString(md.color||'#eee4b8').scale(.65); material.roughness=.25; }
    if(low.includes('grey')||low.includes('metal')){ material.metallic=.18; material.roughness=.48; }
    material.backFaceCulling=false;
    mesh.material=material; mesh.parent=root; mesh.receiveShadows=true;
  }
  if(opt.scale) root.scaling.copyFrom(opt.scale);
  if(opt.rotation) root.rotation.copyFrom(opt.rotation);
  if(opt.position) root.position.copyFrom(opt.position);
  if(opt.pickable===false) for(const ch of root.getChildMeshes()) ch.isPickable=false;
  if(opt.freeze) for(const ch of root.getChildMeshes()) ch.freezeWorldMatrix();
  return root;
}

