  const tex=new B.DynamicTexture('labelTex',{width:1024,height:384},scene,true);tex.hasAlpha=true;const ctx=tex.getContext();ctx.clearRect(0,0,1024,384);ctx.textAlign='center';ctx.textBaseline='middle';
  const font=Math.max(46,Math.min(92,900/(maxLen+2)));ctx.font=`bold ${font}px Arial`;ctx.fillStyle=color;const gap=118,sy=192-(shown.length-1)*gap/2;shown.forEach((ln,i)=>ctx.fillText(ln,512,sy+i*gap));tex.update();
  const m=new B.StandardMaterial('labelMat',scene);m.diffuseTexture=tex;m.emissiveTexture=tex;m.opacityTexture=tex;m.disableLighting=true;p.material=m;return p;
