function updateVRHud(){const tex=G.vrHudTex;if(!tex)return;const ctx=tex.getContext();ctx.clearRect(0,0,900,340);ctx.fillStyle='rgba(10,12,18,.97)';ctx.fillRect(0,0,900,340);const hp=Math.max(0,Math.ceil(G.hp)),pct=Math.max(0,Math.min(1,G.hp/Math.max(1,G.maxHp)));ctx.fillStyle='#fff';ctx.font='bold 96px Arial';ctx.textAlign='left';ctx.fillText(`HP ${hp}`,34,104);ctx.fillStyle='#273041';ctx.fillRect(34,132,832,62);ctx.fillStyle=pct>.5?'#49ef71':pct>.25?'#ffc44b':'#ff4959';ctx.fillRect(34,132,832*pct,62);ctx.fillStyle='#d9ecff';ctx.font='bold 48px Arial';const mode=G.mode==='SURVIVAL'?`SURV W${G.wave||0}`:`LEVEL ${G.meta.survivalLevel||1} W${G.wave||0}/5`;const cc=G.contract&&!G.contract.done?`  ${G.contract.label}:${Math.min(G.contract.goal,Math.floor(G.contract.progress||0))}/${G.contract.goal}`:'';ctx.fillText(`${mode}   ${G.meta.coins||0}C${cc}`,34,284);tex.update();}
function playerBodyCamera(scene){
  // WebXR's camera object persists after the session ends. Use it only during an active session.
  const xr=G.xr?.baseExperience;
  return !G.desktop&&xr?.sessionManager?.inXRSession&&xr.camera ? xr.camera : scene.activeCamera;
}
function rebuildPlayerBody(scene){
  disposeMeshSafe(G.playerBodyRoot); G.playerBodyRoot=null;
  const cam=playerBodyCamera(scene); if(!cam) return;
  const skin=selectedSkinDef();
  const root=new B.TransformNode('playerBodyRoot',scene); root.parent=cam; root.position=new B.Vector3(0,-1.0,0.12);
  {
    const base=playerBaseColor(); const torso=B.MeshBuilder.CreateSphere('potatoTorso',{diameter:.55,segments:14},scene); torso.parent=root; torso.scaling=new B.Vector3(1.0,1.15,.95); torso.position.y=.18; torso.material=mat(scene,'potatoBodyMat',base,.98);
    const cheekL=B.MeshBuilder.CreateSphere('potatoCheekL',{diameter:.36,segments:14},scene); cheekL.parent=root; cheekL.position=new B.Vector3(-.16,-.06,-.15); cheekL.scaling=new B.Vector3(1.08,1.0,1.28); cheekL.material=torso.material;
    const cheekR=cheekL.clone('potatoCheekR'); cheekR.parent=root; cheekR.position.x=.13; root.metadata={potato:true,cheeks:[cheekL,cheekR],torso};
    const tie=box(scene,'potatoTie',new B.Vector3(0,.05,.24),new B.Vector3(.055,.22,.04), '#5a2d0c', root);
    const legL=box(scene,'potLegL',new B.Vector3(-.11,-.34,0),new B.Vector3(.09,.28,.09),'#2a1c15',root);
    const legR=box(scene,'potLegR',new B.Vector3(.11,-.34,0),new B.Vector3(.09,.28,.09),'#2a1c15',root);
    legL.material=legR.material=mat(scene,'potLegMat','#2a1c15',.9);
    const armL=capsule(scene,'potArmL',new B.Vector3(-.30,.16,.02),.42,.045,base,root);armL.rotation.z=.28;
    const armR=capsule(scene,'potArmR',new B.Vector3(.30,.16,.02),.42,.045,base,root);armR.rotation.z=-.28;
    const footL=box(scene,'potFootL',new B.Vector3(-.11,-.51,.055),new B.Vector3(.13,.07,.22),'#241914',root);
    const footR=box(scene,'potFootR',new B.Vector3(.11,-.51,.055),new B.Vector3(.13,.07,.22),'#241914',root);
    root.metadata.arms=[armL,armR];root.metadata.legs=[legL,legR];root.metadata.feet=[footL,footR];
  }
  if(skin.id!=='POTATO'){
    const accentMat=mat(scene,'skinAccentVisual',skin.accent||'#ffffff',.38);accentMat.emissiveColor=B.Color3.FromHexString(skin.accent||'#ffffff').scale(.22);
    if(skin.id==='ROBOT'){for(const x of [-.25,.25]){const pad=box(scene,'robotShoulder',new B.Vector3(x,.32,0),new B.Vector3(.12,.12,.18),skin.accent,root);pad.rotation.z=x<0?-.25:.25;}}
    if(skin.id==='ALIEN'){for(const x of [-.08,.08]){const stalk=capsule(scene,'alienAntenna',new B.Vector3(x,.58,.02),.2,.018,skin.accent,root);stalk.rotation.z=x<0?-.25:.25;const orb=B.MeshBuilder.CreateSphere('alienOrb',{diameter:.06,segments:8},scene);orb.parent=root;orb.position=new B.Vector3(x*1.25,.69,.02);orb.material=accentMat;}}
    if(skin.id==='GOLD'){for(let i=-1;i<=1;i++){const spike=B.MeshBuilder.CreateCylinder('crownSpike',{height:.18,diameterTop:0,diameterBottom:.08,tessellation:8},scene);spike.parent=root;spike.position=new B.Vector3(i*.09,.62,0);spike.material=accentMat;}}
    if(['EMBER_SKIN','FROST_SKIN','VOLT_SKIN','NEON','VOID','SPACE','SHADOW'].includes(skin.id)){const ring=B.MeshBuilder.CreateTorus('skinEnergyRing',{diameter:.48,thickness:.025,tessellation:20},scene);ring.parent=root;ring.position=new B.Vector3(0,-.02,0);ring.rotation.x=Math.PI/2;ring.material=accentMat;}
    if(skin.id==='ROCK'){const plate=box(scene,'rockChest',new B.Vector3(0,.17,.23),new B.Vector3(.25,.24,.045),skin.accent,root);plate.rotation.z=.06;}
    if(skin.id==='SPACE'){const visor=box(scene,'spaceVisor',new B.Vector3(0,.48,.20),new B.Vector3(.28,.12,.04),skin.accent,root);visor.material.emissiveColor=B.Color3.FromHexString(skin.accent).scale(.35);}
    if(skin.id==='CLOWN'){const nose=B.MeshBuilder.CreateSphere('clownNose',{diameter:.09,segments:8},scene);nose.parent=root;nose.position=new B.Vector3(0,.48,.25);nose.material=mat(scene,'clownNoseMat','#ff3d50',.55);}
    if(skin.id==='HAZMAT'){const tank=box(scene,'hazTank',new B.Vector3(0,.18,-.22),new B.Vector3(.18,.32,.12),'#566c37',root);}
    if(skin.id==='SHADOW'){const hood=B.MeshBuilder.CreateTorus('shadowHood',{diameter:.42,thickness:.055,tessellation:16},scene);hood.parent=root;hood.position=new B.Vector3(0,.47,0);hood.material=accentMat;}
    if(skin.id==='JANITOR'){const apron=box(scene,'janitorApron',new B.Vector3(0,.05,.245),new B.Vector3(.28,.28,.035),skin.accent,root);const badge=box(scene,'janitorBadge',new B.Vector3(.13,.30,.245),new B.Vector3(.07,.045,.018),'#f4f0c5',root);}
    if(skin.id==='GLITCH'){for(const y of [-.10,.16,.42]){const r=B.MeshBuilder.CreateTorus('glitchRing',{diameter:.48-y*.12,thickness:.018,tessellation:18},scene);r.parent=root;r.position.y=y;r.rotation.x=Math.PI/2;r.material=accentMat;}}
    if(skin.id==='MAILRUN'){const bag=box(scene,'mailBag',new B.Vector3(.25,.06,-.17),new B.Vector3(.20,.26,.10),'#8b643d',root);bag.rotation.z=-.18;const strap=box(scene,'mailStrap',new B.Vector3(.06,.20,.20),new B.Vector3(.035,.48,.025),skin.accent,root);strap.rotation.z=.62;const cap=box(scene,'mailCap',new B.Vector3(0,.58,.02),new B.Vector3(.28,.06,.22),skin.shirt,root);}
    if(skin.id==='FIREWARDEN'){const vest=box(scene,'wardenVest',new B.Vector3(0,.14,.245),new B.Vector3(.31,.30,.035),skin.shirt,root);for(const y of [.05,.20]){const stripe=box(scene,'wardenStripe',new B.Vector3(0,y,.282),new B.Vector3(.29,.035,.012),skin.accent,root);stripe.material.emissiveColor=B.Color3.FromHexString(skin.accent).scale(.25);}const helm=B.MeshBuilder.CreateCylinder('wardenHelmet',{height:.10,diameter:.42,tessellation:18},scene);helm.parent=root;helm.position=new B.Vector3(0,.59,0);helm.material=mat(scene,'wardenHelmetMat','#d94832',.42);}
  }
  G.playerBodyRoot=root;
}
function updatePlayerBodyVisual(dt){
  const r=G.playerBodyRoot;
  if(!r||!r.metadata?.potato||!hasActivePlayerSession())return;
  // Use simulation time, not performance.now(): XR disconnects must freeze the animation.
  const step=Number.isFinite(dt)&&dt>0?Math.min(dt,.033):0;
  r.metadata.visualTime=(r.metadata.visualTime||0)+step;
  const phase=r.metadata.visualTime;
  const speed=Math.min(1,G.desktop?(G.desktopMoveMagnitude||0):(G.vrMoveMagnitude||0));
  const hit=G.damageFlashT>0?1:0;
  const jig=Math.sin(phase*12)*(0.025+speed*.035+hit*.035);
  const cs=r.metadata.cheeks||[];
  cs.forEach((c,i)=>{if(!c||c.isDisposed?.())return;c.scaling.y=1+Math.abs(jig)*(i?1.05:.9);c.scaling.z=1.28+jig*(i?-1:1);});
  if(r.metadata.torso&&!r.metadata.torso.isDisposed?.())r.metadata.torso.scaling.x=1+jig*.18;
  const walk=Math.sin(phase*9)*speed*.45;
  (r.metadata.arms||[]).forEach((a,i)=>{if(a&&!a.isDisposed?.())a.rotation.x=(i?1:-1)*walk;});
  (r.metadata.legs||[]).forEach((l,i)=>{if(l&&!l.isDisposed?.())l.rotation.x=(i?-1:1)*walk*.8;});
  (r.metadata.feet||[]).forEach((f,i)=>{if(f&&!f.isDisposed?.())f.rotation.x=(i?1:-1)*walk*.25;});
}
function refreshPlayerCosmetics(){
  clearPlayerVisuals();
  if(scene){
    if(G.left) buildHandVisual(scene,'left',G.left);
    if(G.right) buildHandVisual(scene,'right',G.right);
    rebuildPlayerBody(scene);buildVRHud(scene);
  }
}
function npcPalette(role,type='worker'){
  if(type==='boss') return {shirt:'#7a2032',accent:'#ffd166',skin:'#d7a17e'};
  if(role==='thrower') return {shirt:'#48617b',accent:'#79c7ff',skin:'#d0a37f'};
  if(role==='flanker') return {shirt:'#375d49',accent:'#76efb2',skin:'#c99570'};
  return {shirt:'#5f4b8b',accent:'#ff9aa2',skin:'#d8ab88'};
}


