    glove.parent=root;glove.scaling=new B.Vector3(1,1.02,1.16);glove.material=mat(scene,'boxingGloveRed','#ee4d5e',.66);
    part('gloveCuff',new B.Vector3(0,-.23,-.05),new B.Vector3(.30,.17,.32),'#7a2539');
