  for(const n of extras){
    if(!inWave())return false;
    try{n.dropProp?.();}catch{}
    if(!inWave())return false;
    try{n.dispose?.();}catch{
      if(!inWave())return false;
      try{n.root?.dispose?.(false,true);}catch{}
    }
    if(!inWave())return false;
    try{n.dead=true;}catch{}
    if(!inWave())return false;
  }
