  if(G.state!=='shift'||!hasActivePlayerSession()||p.heldBy||p.npcOwner||!Number.isFinite(dt)||dt<=0)return false;
  p.temporaryT=Math.max(0,p.temporaryT-Math.min(.033,dt));
