  const phase=next*7+px*2.3+pz*1.7;
  const nx=vx+Math.sin(phase)*step*.8,nz=vz+Math.cos(phase*.73)*step*.6;
  if(!Number.isFinite(nx)||!Number.isFinite(nz))
    throw Error('invalid paper flutter impulse');
